-- Where and when the member's monthly interest is paid. They are ordinary member details: the officer fills them in,
-- and changing them on an approved member needs a reason, like any other change.
alter table public.members
  add column bank_code text references public.cbn_banks (code),
  add column bank_name text check (bank_name is null or length(trim(bank_name)) > 0),
  add column bank_account_no text check (bank_account_no is null or bank_account_no ~ '^[0-9]{10}$'),
  -- Day of the month interest is paid. In shorter months, days past the end are paid on the last day.
  add column interest_pay_day smallint check (interest_pay_day between 1 and 31),
  add constraint members_bank_details check ((bank_name is null) = (bank_account_no is null));

-- A coded bank always carries the name from the CBN list.
create or replace function app.members_bank_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.bank_code is not null then
    select name into new.bank_name from public.cbn_banks where code = new.bank_code;
  end if;
  return new;
end;
$$;

create trigger members_bank_guard
  before insert or update of bank_code, bank_name on public.members
  for each row execute function app.members_bank_guard();

-- Annual interest rate per plan. The figures are placeholders until Kuun confirms its rates and interest formula.
alter table public.plan_types
  add column interest_rate numeric(5, 2) not null default 0 check (interest_rate between 0 and 100);
update public.plan_types set interest_rate = case code when 'silver' then 10 when 'gold' then 12 when 'platinum' then 15 else 0 end;

-- Each plan keeps the rate it was opened at, so a later change to the plan type doesn't rewrite existing plans.
alter table public.member_plans
  add column interest_rate numeric(5, 2) check (interest_rate between 0 and 100);
-- The plan guard blocks direct updates (plans change only through the plan workflow), so step around it for the
-- one-off backfill of plans that already exist.
alter table public.member_plans disable trigger member_plans_guard;
update public.member_plans p set interest_rate = t.interest_rate from public.plan_types t where t.code = p.plan_type;
alter table public.member_plans enable trigger member_plans_guard;
alter table public.member_plans alter column interest_rate set not null;

create or replace function app.member_plans_rate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    select interest_rate into new.interest_rate from public.plan_types where code = new.plan_type;
  end if;
  return new;
end;
$$;

create trigger member_plans_rate
  before insert on public.member_plans
  for each row execute function app.member_plans_rate();

-- The payments due on a date: members whose interest pay day it is, with their bank details, savings at that date and
-- the month's interest. Placeholder formula until Kuun confirms it: for each active plan, verified contributions to
-- date times the plan's annual rate, divided by 12.
create or replace function public.interest_payment_schedule(p_date date, p_branch_id uuid default null, p_region_id uuid default null)
returns table (
  member_id uuid, membership_no text, beneficiary_name text, branch_id uuid, branch_name text,
  bank_name text, bank_code text, bank_account_no text, total_savings numeric, interest_rate numeric, amount numeric
)
language sql
stable
security invoker
set search_path = ''
as $$
  with due as (
    select m.*, b.name as branch_name
    from public.members m
    join public.branches b on b.id = m.branch_id
    where m.status = 'approved'
      and m.interest_pay_day is not null
      and (m.interest_pay_day = extract(day from p_date)
           or (p_date = (date_trunc('month', p_date) + interval '1 month - 1 day')::date
               and m.interest_pay_day > extract(day from p_date)))
      and (p_branch_id is null or m.branch_id = p_branch_id)
      and (p_region_id is null or b.region_id = p_region_id)
  ),
  plans as (
    select p.member_id, p.interest_rate, coalesce(sum(c.amount), 0) as savings
    from public.member_plans p
    join due d on d.id = p.member_id
    left join public.contributions c on c.member_plan_id = p.id and c.verified_at is not null and c.paid_on <= p_date
    where p.status = 'active' and p.start_date <= p_date
    group by p.id
  )
  select d.id, d.membership_no, concat_ws(' ', d.first_name, d.middle_name, d.last_name), d.branch_id, d.branch_name,
         d.bank_name, d.bank_code, d.bank_account_no,
         sum(p.savings)::numeric(16, 2),
         round(sum(p.savings * p.interest_rate) / sum(p.savings), 2),
         sum(round(p.savings * p.interest_rate / 100 / 12, 2))::numeric(16, 2)
  from due d
  join plans p on p.member_id = d.id
  group by d.id, d.membership_no, d.first_name, d.middle_name, d.last_name, d.branch_id, d.branch_name,
           d.bank_name, d.bank_code, d.bank_account_no
  having sum(p.savings) > 0
  order by d.branch_name, d.last_name, d.first_name;
$$;

-- ====================================================================================================
-- 20261104000001_upload_staging.sql
-- ====================================================================================================

-- Browsers upload files straight to this bucket, and the server action then reads them from here. Vercel refuses
-- request bodies over 4.5 MB, so a file sent through a server action failed long before our 10 MB limit.
-- Each staff member writes only under a folder named after their own id; the server moves on what it needs and
-- removes the staged copy.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('upload-staging', 'upload-staging', false, 10485760, null)
on conflict (id) do nothing;

create policy "staff stage their own uploads" on storage.objects for insert to authenticated
  with check (bucket_id = 'upload-staging' and (storage.foldername(name))[1] = auth.uid()::text);

create policy "staff read their own staged uploads" on storage.objects for select to authenticated
  using (bucket_id = 'upload-staging' and (storage.foldername(name))[1] = auth.uid()::text);

create policy "staff clear their own staged uploads" on storage.objects for delete to authenticated
  using (bucket_id = 'upload-staging' and (storage.foldername(name))[1] = auth.uid()::text);

-- ====================================================================================================
-- 20261104000002_payments_all_branches.sql
-- ====================================================================================================

-- Payments Accountants see and pay payment requests from every branch.
--
-- Until now a Payments Accountant only saw the payment requests of the branch
-- (or region) their role was assigned to. Kuun's Payments desk pays for the
-- whole organisation, so the role gets a new permission that lifts the branch
-- limit for payment requests only. Receipts, journals, reconciliations and
-- raising new requests keep their branch limits.

insert into public.permissions (code, description) values
  ('accounts.payments.all_branches', 'See and pay payment requests from every branch, not just your own')
on conflict (code) do nothing;

insert into public.role_permissions (role_code, permission_code) values
  ('payments_accountant', 'accounts.payments.all_branches')
on conflict do nothing;

-- True when the storage path sits in a payment request's evidence folder
-- (<branch id>/<transaction id>/<file>). Used by the storage policies below.
create or replace function app.storage_path_is_payment(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when (storage.foldername(p_name))[2] ~ '^[0-9a-f-]{36}$' then exists (
      select 1 from public.finance_transactions t
       where t.id = (storage.foldername(p_name))[2]::uuid
         and t.branch_id = app.storage_path_branch(p_name)
         and t.direction = 'payment'
    )
    else false
  end;
$$;

revoke all on function app.storage_path_is_payment(text) from public, anon;
grant execute on function app.storage_path_is_payment(text) to authenticated;

-- See every branch's payment requests, their evidence and the bank account they come out of.
create policy "payments desk reads every branch's payment requests" on public.finance_transactions for select to authenticated
  using (direction = 'payment' and app.has_permission('accounts.payments.all_branches'));

create policy "payments desk reads every branch's payment evidence" on public.finance_attachments for select to authenticated
  using (
    app.has_permission('accounts.payments.all_branches')
    and exists (select 1 from public.finance_transactions t where t.id = transaction_id and t.direction = 'payment')
  );

create policy "payments desk reads every branch's bank accounts" on public.bank_accounts for select to authenticated
  using (app.has_permission('accounts.payments.all_branches'));

-- Attach proof of payment to any branch's approved payment (the attachments
-- trigger still checks the status and the folder).
create policy "payments desk attaches proof of payment in any branch" on public.finance_attachments for insert to authenticated
  with check (
    kind = 'payment_proof'
    and app.has_permission('accounts.payments.all_branches')
    and exists (select 1 from public.finance_transactions t where t.id = transaction_id and t.direction = 'payment')
  );

create policy "payments desk downloads payment evidence in any branch" on storage.objects for select to authenticated
  using (
    bucket_id = 'finance-evidence'
    and app.has_permission('accounts.payments.all_branches')
    and app.storage_path_is_payment(name)
  );

create policy "payments desk uploads proof of payment in any branch" on storage.objects for insert to authenticated
  with check (
    bucket_id = 'finance-evidence'
    and app.has_permission('accounts.payments.all_branches')
    and app.storage_path_is_payment(name)
  );

-- Unchanged, except that the payments desk can pay any branch's payment.
create or replace function public.pay_finance_transaction(p_id uuid)
returns public.finance_transactions
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_txn public.finance_transactions;
begin
  select * into v_txn from public.finance_transactions where id = p_id for update;
  if not found or not (
    app.has_branch_permission('accounts.payments.pay', v_txn.branch_id)
    or (v_txn.direction = 'payment' and app.has_permission('accounts.payments.pay')
        and app.has_permission('accounts.payments.all_branches'))
  ) then
    raise exception 'transaction not found' using errcode = 'no_data_found';
  end if;
  if v_txn.direction <> 'payment' or v_txn.status <> 'approved' then
    raise exception 'only approved payments can be marked as paid' using errcode = 'check_violation';
  end if;
  if v_txn.audited_at is null then
    raise exception 'Internal Audit has to approve this payment before it is paid' using errcode = 'check_violation';
  end if;
  if auth.uid() = v_txn.approved_by then
    raise exception 'you approved this payment, so someone else must make it' using errcode = 'insufficient_privilege';
  end if;
  if not exists (select 1 from public.finance_attachments a where a.transaction_id = p_id and a.kind = 'payment_proof') then
    raise exception 'attach proof of payment first' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.finance_transactions set paid_by = auth.uid(), paid_at = now() where id = p_id;
  perform app.end_workflow();
  perform app.post_finance_transaction(p_id);

  select * into v_txn from public.finance_transactions where id = p_id;
  return v_txn;
end;
$$;

-- ====================================================================================================
-- 20261104000003_liquidations_payment_returns.sql
-- ====================================================================================================

-- Two flows from version 3 of the Accounts department flowchart:
--   1. Liquidation of a member's savings: Operations raises the request with the member's bank details, the Branch
--      Manager approves it, and Accounts pays it out through the usual payment chain (Accounts approval, Internal
--      Audit, proof of payment). When the payout posts, the plan is closed as liquidated.
--   2. The accountant who pays checks an approved payment before paying it. If the approval, amount, beneficiary or
--      documents aren't right, they send it back to the requester with the reason, and it isn't paid.

-- ===========================================================================
-- 1. Liquidation of a member's savings
-- ===========================================================================

insert into public.permissions (code, description) values
  ('liquidations.request', 'Raise a request to pay out a member''s savings when they liquidate their plan'),
  ('liquidations.approve', 'Approve, return or reject liquidation requests before Accounts pays them')
on conflict (code) do nothing;

insert into public.role_permissions (role_code, permission_code) values
  ('admin_officer', 'liquidations.request'),
  ('head_of_administration', 'liquidations.request'),
  ('branch_manager', 'liquidations.approve')
on conflict do nothing;

create sequence if not exists public.liquidation_no_seq;

create table public.plan_liquidations (
  id uuid primary key default gen_random_uuid(),
  liquidation_no text not null unique,
  member_plan_id uuid not null references public.member_plans (id) on delete restrict,
  member_id uuid not null references public.members (id) on delete restrict,
  branch_id uuid not null references public.branches (id),
  -- What is paid out, and the plan's verified savings when the request was raised, for the Branch Manager to compare.
  amount numeric(14, 2) not null check (amount > 0),
  plan_savings numeric(16, 2) not null default 0,
  -- Where the money goes.
  beneficiary_account_name text not null check (length(trim(beneficiary_account_name)) > 1),
  bank_code text references public.cbn_banks (code),
  bank_name text not null check (length(trim(bank_name)) > 0),
  bank_account_no text not null check (bank_account_no ~ '^[0-9]{10}$'),
  note text,
  status text not null default 'pending_approval'
    check (status in ('pending_approval', 'returned', 'approved', 'paid', 'rejected', 'cancelled')),
  requested_by uuid not null references public.staff (id),
  requested_at timestamptz not null default now(),
  decided_by uuid references public.staff (id),
  decided_at timestamptz,
  decision_note text,
  -- The payment in Accounts, kept in step by a trigger on finance_transactions.
  payment_txn_id uuid,
  payment_txn_no text,
  payment_status text,
  paid_at timestamptz,
  created_at timestamptz not null default now()
);
create index plan_liquidations_branch_status_idx on public.plan_liquidations (branch_id, status);
create index plan_liquidations_member_idx on public.plan_liquidations (member_id);
-- One open request per plan.
create unique index plan_liquidations_one_open_idx on public.plan_liquidations (member_plan_id)
  where status in ('pending_approval', 'returned', 'approved');

-- Rows change only through the functions below.
create or replace function app.plan_liquidations_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not app.in_workflow() then
    raise exception 'liquidation requests change only through the liquidation workflow' using errcode = 'insufficient_privilege';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'liquidation requests are never deleted; cancel them instead' using errcode = 'insufficient_privilege';
  end if;
  if new.bank_code is not null then
    select name into new.bank_name from public.cbn_banks where code = new.bank_code;
  end if;
  return new;
end;
$$;

create trigger plan_liquidations_guard
  before insert or update or delete on public.plan_liquidations
  for each row execute function app.plan_liquidations_guard();

select app.enable_audit('public.plan_liquidations');

alter table public.plan_liquidations enable row level security;
create policy "operations and accounts read liquidations in their branches" on public.plan_liquidations for select to authenticated
  using (
    app.has_branch_permission('members.read', branch_id)
    or app.has_branch_permission('accounts.read', branch_id)
  );

-- A plan's verified savings at a date: the same figure the interest schedule uses.
create or replace function app.plan_savings(p_plan_id uuid, p_date date default current_date)
returns numeric
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(c.amount), 0)::numeric(16, 2)
  from public.contributions c
  where c.member_plan_id = p_plan_id and c.verified_at is not null and c.paid_on <= p_date;
$$;
revoke all on function app.plan_savings(uuid, date) from public, anon;
grant execute on function app.plan_savings(uuid, date) to authenticated;

-- Operations raises a liquidation request, or corrects and resends one the Branch Manager or Accounts sent back.
create or replace function public.request_liquidation(
  p_id uuid, p_plan_id uuid, p_amount numeric, p_account_name text, p_bank_code text, p_bank_name text,
  p_account_no text, p_note text
)
returns public.plan_liquidations
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_plan public.member_plans;
  v_row public.plan_liquidations;
begin
  if p_id is not null then
    select * into v_row from public.plan_liquidations where id = p_id for update;
    if not found or not app.has_branch_permission('liquidations.request', v_row.branch_id) then
      raise exception 'liquidation request not found' using errcode = 'no_data_found';
    end if;
    if v_row.status <> 'returned' then
      raise exception 'only a request that was sent back can be changed and sent again' using errcode = 'check_violation';
    end if;
    p_plan_id := v_row.member_plan_id;
  end if;

  select * into v_plan from public.member_plans where id = p_plan_id;
  if not found or not app.has_branch_permission('liquidations.request', v_plan.branch_id) then
    raise exception 'plan not found' using errcode = 'no_data_found';
  end if;
  if v_plan.status not in ('active', 'matured') then
    raise exception 'this plan is % and can''t be liquidated', v_plan.status using errcode = 'check_violation';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'enter the amount to pay the member' using errcode = 'check_violation';
  end if;
  if p_account_name is null or length(trim(p_account_name)) < 2 then
    raise exception 'enter the name on the member''s bank account' using errcode = 'check_violation';
  end if;
  if nullif(trim(coalesce(p_bank_code, '')), '') is null and nullif(trim(coalesce(p_bank_name, '')), '') is null then
    raise exception 'choose the member''s bank' using errcode = 'check_violation';
  end if;
  if p_account_no is null or trim(p_account_no) !~ '^[0-9]{10}$' then
    raise exception 'the account number must be 10 digits' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  if p_id is null then
    insert into public.plan_liquidations (
      liquidation_no, member_plan_id, member_id, branch_id, amount, plan_savings, beneficiary_account_name, bank_code,
      bank_name, bank_account_no, note, status, requested_by, requested_at
    ) values (
      'LIQ-' || lpad(nextval('public.liquidation_no_seq')::text, 6, '0'), v_plan.id, v_plan.member_id, v_plan.branch_id,
      p_amount, app.plan_savings(v_plan.id), trim(p_account_name), nullif(trim(coalesce(p_bank_code, '')), ''),
      coalesce(nullif(trim(coalesce(p_bank_name, '')), ''), '-'), trim(p_account_no), nullif(trim(coalesce(p_note, '')), ''),
      'pending_approval', auth.uid(), now()
    ) returning * into v_row;
  else
    update public.plan_liquidations
       set amount = p_amount, plan_savings = app.plan_savings(v_plan.id), beneficiary_account_name = trim(p_account_name),
           bank_code = nullif(trim(coalesce(p_bank_code, '')), ''),
           bank_name = coalesce(nullif(trim(coalesce(p_bank_name, '')), ''), '-'), bank_account_no = trim(p_account_no),
           note = nullif(trim(coalesce(p_note, '')), ''), status = 'pending_approval', requested_by = auth.uid(),
           requested_at = now(), decided_by = null, decided_at = null
     where id = p_id
     returning * into v_row;
  end if;
  perform app.end_workflow();
  return v_row;
exception
  when unique_violation then
    raise exception 'this plan already has a liquidation request in progress' using errcode = 'check_violation';
end;
$$;

-- The Branch Manager approves (on to Accounts) or rejects a request.
create or replace function public.decide_liquidation(p_id uuid, p_approve boolean, p_note text)
returns public.plan_liquidations
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.plan_liquidations;
begin
  select * into v_row from public.plan_liquidations where id = p_id for update;
  if not found or not app.has_branch_permission('liquidations.approve', v_row.branch_id) then
    raise exception 'liquidation request not found' using errcode = 'no_data_found';
  end if;
  if v_row.status <> 'pending_approval' then
    raise exception 'only requests waiting for the Branch Manager can be decided' using errcode = 'check_violation';
  end if;
  if auth.uid() = v_row.requested_by then
    raise exception 'you raised this request, so someone else must approve it' using errcode = 'insufficient_privilege';
  end if;
  if not p_approve and (p_note is null or length(trim(p_note)) < 5) then
    raise exception 'say why the request is rejected' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.plan_liquidations
     set status = case when p_approve then 'approved' else 'rejected' end, decided_by = auth.uid(), decided_at = now(),
         decision_note = nullif(trim(coalesce(p_note, '')), '')
   where id = p_id
   returning * into v_row;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- Back to Operations for correction: by the Branch Manager before deciding, or by Accounts before paying (while no
-- payment for it is in progress).
create or replace function public.return_liquidation(p_id uuid, p_reason text)
returns public.plan_liquidations
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.plan_liquidations;
  v_by text;
begin
  select * into v_row from public.plan_liquidations where id = p_id for update;
  if not found then
    raise exception 'liquidation request not found' using errcode = 'no_data_found';
  end if;
  if v_row.status = 'pending_approval' and app.has_branch_permission('liquidations.approve', v_row.branch_id) then
    v_by := 'Branch Manager';
    if auth.uid() = v_row.requested_by then
      raise exception 'you raised this request, so someone else must review it' using errcode = 'insufficient_privilege';
    end if;
  elsif v_row.status = 'approved' and app.has_branch_permission('accounts.payments.request', v_row.branch_id) then
    v_by := 'Accounts';
    if exists (
      select 1 from public.finance_transactions t
      where t.liquidation_id = p_id and t.status not in ('rejected', 'reversed')
    ) then
      raise exception 'a payment for this request is in progress in Accounts; reject that payment first' using errcode = 'check_violation';
    end if;
  elsif app.has_branch_permission('liquidations.approve', v_row.branch_id)
     or app.has_branch_permission('accounts.payments.request', v_row.branch_id) then
    raise exception 'this request can''t be sent back now' using errcode = 'check_violation';
  else
    raise exception 'liquidation request not found' using errcode = 'no_data_found';
  end if;
  if p_reason is null or length(trim(p_reason)) < 5 then
    raise exception 'say what needs correcting' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.plan_liquidations
     set status = 'returned', decided_by = auth.uid(), decided_at = now(), decision_note = v_by || ': ' || trim(p_reason)
   where id = p_id
   returning * into v_row;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- Operations withdraws a request that hasn't been approved (for example, the member changed their mind).
create or replace function public.cancel_liquidation(p_id uuid, p_reason text)
returns public.plan_liquidations
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.plan_liquidations;
begin
  select * into v_row from public.plan_liquidations where id = p_id for update;
  if not found or not app.has_branch_permission('liquidations.request', v_row.branch_id) then
    raise exception 'liquidation request not found' using errcode = 'no_data_found';
  end if;
  if v_row.status not in ('pending_approval', 'returned') then
    raise exception 'only requests that aren''t approved yet can be cancelled' using errcode = 'check_violation';
  end if;
  if p_reason is null or length(trim(p_reason)) < 5 then
    raise exception 'say why the request is cancelled' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.plan_liquidations
     set status = 'cancelled', decision_note = 'Cancelled: ' || trim(p_reason), decided_by = auth.uid(), decided_at = now()
   where id = p_id
   returning * into v_row;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- The payment that pays out an approved liquidation.
alter table public.finance_transactions
  add column liquidation_id uuid references public.plan_liquidations (id);
create index finance_transactions_liquidation_idx on public.finance_transactions (liquidation_id) where liquidation_id is not null;

-- Runs after finance_transactions_guard (alphabetical order). A payout matches its approved request exactly.
create or replace function app.finance_transactions_liquidation_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.plan_liquidations;
begin
  if tg_op = 'UPDATE' and app.in_workflow() then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.liquidation_id is distinct from old.liquidation_id then
    raise exception 'a payout stays with its liquidation request; reject it and raise a new one' using errcode = 'check_violation';
  end if;
  if new.liquidation_id is null then
    return new;
  end if;

  select * into v_row from public.plan_liquidations where id = new.liquidation_id;
  if v_row.status <> 'approved' then
    raise exception 'only liquidation requests the Branch Manager approved can be paid' using errcode = 'check_violation';
  end if;
  if new.direction <> 'payment' or new.transaction_type <> 'savings_withdrawal' then
    raise exception 'a liquidation is paid as a member savings withdrawal' using errcode = 'check_violation';
  end if;
  if new.branch_id <> v_row.branch_id then
    raise exception 'pay the liquidation from a bank or cash account of the member''s branch' using errcode = 'check_violation';
  end if;
  if new.amount <> v_row.amount then
    raise exception 'the payout must be the approved amount of ₦%', to_char(v_row.amount, 'FM999,999,999,990.00')
      using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.finance_transactions t
    where t.liquidation_id = new.liquidation_id and t.id <> new.id and t.status not in ('rejected', 'reversed')
  ) then
    raise exception 'this liquidation already has a payment in Accounts' using errcode = 'check_violation';
  end if;
  new.member_id := v_row.member_id;
  return new;
end;
$$;

create trigger finance_transactions_liquidation_guard
  before insert or update on public.finance_transactions
  for each row execute function app.finance_transactions_liquidation_guard();

-- Keeps the liquidation in step with its payment, and closes the plan when the payout posts.
create or replace function app.finance_transactions_liquidation_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_was_on boolean := app.in_workflow();
  v_row public.plan_liquidations;
begin
  if new.liquidation_id is null or (tg_op = 'UPDATE' and new.status is not distinct from old.status) then
    return null;
  end if;
  select * into v_row from public.plan_liquidations where id = new.liquidation_id for update;
  perform app.begin_workflow();
  update public.plan_liquidations
     set payment_txn_id = new.id, payment_txn_no = new.txn_no, payment_status = new.status::text
   where id = v_row.id;
  if new.status = 'posted' then
    update public.plan_liquidations set status = 'paid', paid_at = now() where id = v_row.id;
    update public.member_plans set status = 'liquidated', closed_at = now() where id = v_row.member_plan_id;
  elsif new.status = 'reversed' and v_row.status = 'paid' then
    update public.plan_liquidations set status = 'approved', paid_at = null where id = v_row.id;
    update public.member_plans set status = 'active', closed_at = null where id = v_row.member_plan_id;
  end if;
  if not v_was_on then
    perform app.end_workflow();
  end if;
  return null;
end;
$$;

create trigger finance_transactions_liquidation_events
  after insert or update on public.finance_transactions
  for each row execute function app.finance_transactions_liquidation_events();

-- Accounts raises the payout for an approved liquidation and sends it for approval. The Branch Manager's approval is
-- its supporting document, so no upload is needed.
create or replace function public.raise_liquidation_payment(p_id uuid, p_bank_account_id uuid, p_txn_date date default current_date)
returns public.finance_transactions
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.plan_liquidations;
  v_plan_name text;
  v_attempt int;
  v_txn public.finance_transactions;
begin
  select * into v_row from public.plan_liquidations where id = p_id for update;
  if not found or not app.has_branch_permission('accounts.payments.request', v_row.branch_id) then
    raise exception 'liquidation request not found' using errcode = 'no_data_found';
  end if;
  if not exists (select 1 from public.bank_accounts b where b.id = p_bank_account_id and b.branch_id = v_row.branch_id and b.is_active) then
    raise exception 'choose an active bank or cash account of the member''s branch' using errcode = 'check_violation';
  end if;
  select pt.name into v_plan_name
  from public.member_plans p join public.plan_types pt on pt.code = p.plan_type where p.id = v_row.member_plan_id;
  select count(*) + 1 into v_attempt from public.finance_transactions where liquidation_id = p_id;

  insert into public.finance_transactions (
    direction, transaction_type, txn_date, amount, bank_account_id, member_id, liquidation_id, counterparty, reference,
    description, branch_id
  ) values (
    'payment', 'savings_withdrawal', coalesce(p_txn_date, current_date), v_row.amount, p_bank_account_id, v_row.member_id,
    p_id, v_row.beneficiary_account_name,
    v_row.liquidation_no || case when v_attempt > 1 then '/' || v_attempt else '' end,
    format('Liquidation %s of %s plan: pay %s, %s %s', v_row.liquidation_no, v_plan_name, v_row.beneficiary_account_name,
           v_row.bank_name, v_row.bank_account_no),
    v_row.branch_id
  ) returning * into v_txn;

  return public.submit_finance_transaction(v_txn.id);
end;
$$;

-- Unchanged, except that a liquidation payout uses the Branch Manager's approval as its evidence.
create or replace function public.submit_finance_transaction(p_id uuid)
returns public.finance_transactions
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_txn public.finance_transactions;
begin
  select * into v_txn from public.finance_transactions where id = p_id for update;
  if not found or not app.has_branch_permission(
    case when v_txn.direction = 'receipt' then 'accounts.receipts.record' else 'accounts.payments.request' end, v_txn.branch_id
  ) then
    raise exception 'transaction not found' using errcode = 'no_data_found';
  end if;
  if v_txn.status not in ('draft', 'returned') then
    raise exception 'only draft or returned transactions can be submitted' using errcode = 'check_violation';
  end if;
  if v_txn.contribution_id is null and v_txn.statement_line_id is null
     and not (v_txn.transaction_type = 'loan_disbursement' and v_txn.loan_id is not null)
     and v_txn.liquidation_id is null
     and not exists (select 1 from public.finance_attachments a where a.transaction_id = p_id and a.kind = 'supporting') then
    raise exception 'attach the supporting evidence (receipt, invoice or approval) before submitting' using errcode = 'check_violation';
  end if;
  if v_txn.needs_ops_confirmation and v_txn.transaction_type = 'member_savings' and v_txn.member_plan_id is null then
    raise exception 'choose the savings plan the money was paid into' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.finance_transactions
     set status = 'submitted', submitted_by = auth.uid(), submitted_at = now(), decision_reason = null,
         ops_confirmed_by = null, ops_confirmed_at = null, ops_note = null
   where id = p_id
   returning * into v_txn;
  perform app.end_workflow();
  return v_txn;
end;
$$;

-- Operations, the Branch Manager and Accounts see each other's names on a liquidation without reading the staff
-- directory: the queue for a page comes from here.
create or replace function public.liquidation_requests(p_status text[] default null)
returns table (
  id uuid, liquidation_no text, branch_id uuid, branch_name text, status text, amount numeric, plan_savings numeric,
  member_id uuid, member_name text, membership_no text, member_plan_id uuid, plan_name text, start_date date,
  maturity_date date, beneficiary_account_name text, bank_code text, bank_name text, bank_account_no text, note text,
  requested_by uuid, requested_by_name text, requested_at timestamptz, decided_by uuid, decided_by_name text,
  decided_at timestamptz, decision_note text, payment_txn_id uuid, payment_txn_no text, payment_status text, paid_at timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select l.id, l.liquidation_no, l.branch_id, b.name, l.status, l.amount, l.plan_savings,
         m.id, concat_ws(' ', m.first_name, m.middle_name, m.last_name), m.membership_no, p.id, pt.name, p.start_date,
         p.maturity_date, l.beneficiary_account_name, l.bank_code, l.bank_name, l.bank_account_no, l.note,
         l.requested_by, rs.full_name, l.requested_at, l.decided_by, ds.full_name, l.decided_at, l.decision_note,
         l.payment_txn_id, l.payment_txn_no, l.payment_status, l.paid_at
  from public.plan_liquidations l
  join public.branches b on b.id = l.branch_id
  join public.members m on m.id = l.member_id
  join public.member_plans p on p.id = l.member_plan_id
  join public.plan_types pt on pt.code = p.plan_type
  join public.staff rs on rs.id = l.requested_by
  left join public.staff ds on ds.id = l.decided_by
  where (p_status is null or l.status = any (p_status))
    and (app.has_branch_permission('members.read', l.branch_id) or app.has_branch_permission('accounts.read', l.branch_id))
  order by l.requested_at desc;
$$;

revoke all on function public.request_liquidation(uuid, uuid, numeric, text, text, text, text, text) from public, anon;
revoke all on function public.decide_liquidation(uuid, boolean, text) from public, anon;
revoke all on function public.return_liquidation(uuid, text) from public, anon;
revoke all on function public.cancel_liquidation(uuid, text) from public, anon;
revoke all on function public.raise_liquidation_payment(uuid, uuid, date) from public, anon;
revoke all on function public.liquidation_requests(text[]) from public, anon;
grant execute on function public.request_liquidation(uuid, uuid, numeric, text, text, text, text, text) to authenticated;
grant execute on function public.decide_liquidation(uuid, boolean, text) to authenticated;
grant execute on function public.return_liquidation(uuid, text) to authenticated;
grant execute on function public.cancel_liquidation(uuid, text) to authenticated;
grant execute on function public.raise_liquidation_payment(uuid, uuid, date) to authenticated;
grant execute on function public.liquidation_requests(text[]) to authenticated;

-- ===========================================================================
-- 2. The paying accountant can send an approved payment back instead of paying it
-- ===========================================================================

-- Checks before paying: the approvals, amount, beneficiary and documents. If something is wrong, the payment goes back
-- to whoever requested it, with the reason, and must be approved again (by Accounts and Internal Audit) after the fix.
create or replace function public.return_payment_before_paying(p_id uuid, p_reason text)
returns public.finance_transactions
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_txn public.finance_transactions;
begin
  select * into v_txn from public.finance_transactions where id = p_id for update;
  if not found or not (
    app.has_branch_permission('accounts.payments.pay', v_txn.branch_id)
    -- The payments desk that pays for every branch (when that permission exists).
    or (v_txn.direction = 'payment' and app.has_permission('accounts.payments.pay')
        and app.has_permission('accounts.payments.all_branches'))
  ) then
    raise exception 'transaction not found' using errcode = 'no_data_found';
  end if;
  if v_txn.direction <> 'payment' or v_txn.status <> 'approved' then
    raise exception 'only approved payments that haven''t been paid can be sent back here' using errcode = 'check_violation';
  end if;
  if p_reason is null or length(trim(p_reason)) < 5 then
    raise exception 'say what needs correcting before this can be paid' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.finance_transactions
     set status = 'returned', decision_reason = 'Payments: ' || trim(p_reason),
         approved_by = null, approved_at = null, audited_by = null, audited_at = null
   where id = p_id
   returning * into v_txn;
  perform app.end_workflow();
  return v_txn;
end;
$$;

revoke all on function public.return_payment_before_paying(uuid, text) from public, anon;
grant execute on function public.return_payment_before_paying(uuid, text) to authenticated;

-- ====================================================================================================
-- 20261111000001_branch_manager_member_view.sql
-- ====================================================================================================

-- Branch Managers review everything about a member in their branch.
--
-- Until now a Branch Manager saw a member's file, documents, plans and contributions, but not the member's loans
-- (with their guarantors and schedules), the money Accounts paid in or out for the member, or the history of changes
-- to the file. This gives them all three, read-only and limited to the branches their role covers:
--
--   * credit.read + module.credit: the member's loans and the Credit pages, read-only (every Credit action needs a
--     further permission the Branch Manager doesn't have).
--   * members.full_view: two read-only functions for the member page, one listing the member's receipts and payments,
--     one listing the changes made to the member's records. Head of Administration and Internal Audit get it too.

insert into public.permissions (code, description) values
  ('members.full_view', 'See everything about a member: money paid in and out for them, and the history of their file')
on conflict (code) do nothing;

insert into public.role_permissions (role_code, permission_code) values
  ('branch_manager', 'members.full_view'),
  ('branch_manager', 'credit.read'),
  ('branch_manager', 'module.credit'),
  ('head_of_administration', 'members.full_view'),
  ('internal_auditor', 'members.full_view')
on conflict do nothing;

-- The member's receipts and payments (savings in, interest out, liquidation payouts, loan disbursements and
-- repayments), whatever their stage after draft. Accounts' transactions are otherwise only readable by Accounts.
create or replace function public.member_money_history(p_member_id uuid)
returns table (
  id uuid, txn_no text, direction text, transaction_type text, type_name text, status public.finance_status,
  txn_date date, amount numeric, interest_amount numeric, reference text, description text,
  member_plan_id uuid, plan_name text, loan_id uuid, loan_no text, liquidation_id uuid, liquidation_no text,
  paid_at timestamptz, posted_at timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select t.id, t.txn_no, t.direction, t.transaction_type, r.name, t.status,
         t.txn_date, t.amount, t.interest_amount, t.reference, t.description,
         t.member_plan_id, pt.name, t.loan_id, l.loan_no, t.liquidation_id, q.liquidation_no,
         t.paid_at, t.posted_at
  from public.members m
  join public.finance_transactions t on t.member_id = m.id
  join public.posting_rules r on r.transaction_type = t.transaction_type
  left join public.member_plans p on p.id = t.member_plan_id
  left join public.plan_types pt on pt.code = p.plan_type
  left join public.loans l on l.id = t.loan_id
  left join public.plan_liquidations q on q.id = t.liquidation_id
  where m.id = p_member_id
    and t.status <> 'draft'
    and app.has_branch_permission('members.full_view', m.branch_id)
  order by t.txn_date desc, t.created_at desc;
$$;

-- Who changed what on the member's file, plans, contributions, documents and liquidations (and loans, for staff who
-- can read loans). Field names, the new status and which record it was: the other values stay in the audit trail.
create or replace function public.member_history(p_member_id uuid)
returns table (
  occurred_at timestamptz, actor_id uuid, actor_name text, record_type text, record_id text, action text,
  changed_fields text[], status text, detail text
)
language sql
stable
security definer
set search_path = ''
as $$
  select a.occurred_at, a.actor_id, s.full_name,
         replace(a.table_name, 'public.', ''), a.record_id, a.action,
         array(select f from unnest(a.changed_fields) f where f not in ('updated_at')),
         case when a.action = 'INSERT' or 'status' = any (a.changed_fields) then a.new_data ->> 'status' end,
         -- Which record: the loan or liquidation number, the document or plan type, or the contribution's amount.
         coalesce(
           coalesce(a.new_data, a.old_data) ->> 'loan_no',
           coalesce(a.new_data, a.old_data) ->> 'liquidation_no',
           coalesce(a.new_data, a.old_data) ->> 'document_type',
           coalesce(a.new_data, a.old_data) ->> 'plan_type',
           case when a.table_name = 'public.contributions' then coalesce(a.new_data, a.old_data) ->> 'amount' end
         )
  from public.members m
  join public.audit_log a on a.branch_id = m.branch_id
  left join public.staff s on s.id = a.actor_id
  where m.id = p_member_id
    and app.has_branch_permission('members.full_view', m.branch_id)
    and (
      (a.table_name = 'public.members' and a.record_id = m.id::text)
      or (
        a.table_name in ('public.member_plans', 'public.contributions', 'public.member_documents', 'public.plan_liquidations')
        and coalesce(a.new_data, a.old_data) ->> 'member_id' = m.id::text
      )
      or (
        a.table_name = 'public.loans'
        and coalesce(a.new_data, a.old_data) ->> 'member_id' = m.id::text
        and app.has_branch_permission('credit.read', m.branch_id)
      )
    )
  order by a.occurred_at desc, a.id desc
  limit 300;
$$;

revoke all on function public.member_money_history(uuid) from public, anon;
revoke all on function public.member_history(uuid) from public, anon;
grant execute on function public.member_money_history(uuid) to authenticated;
grant execute on function public.member_history(uuid) to authenticated;

-- ====================================================================================================
-- 20261111000002_top_ups_from_accounts.sql
-- ====================================================================================================

-- Member top ups now start in Accounts.
--   1. Accounts sees the money arrive, records the top up (amount, date, how it was paid, reference, who paid it) and
--      chooses the branch it belongs to.
--   2. That branch's Operations officer finds the member and plan and logs it. Logging creates the member's top-up
--      contribution with exactly the amount, date and reference Accounts gave, so the officer can't change them.
--   3. From there it follows the usual contribution path: the Branch Manager verifies it and Accounts posts it.
-- If the branch can't match it to a member, the officer sends it back with the reason, and Accounts sends it to another
-- branch or cancels it. Operations can no longer record a top-up on its own.

create sequence if not exists public.top_up_no_seq;

create table public.top_up_requests (
  id uuid primary key default gen_random_uuid(),
  top_up_no text not null unique,
  branch_id uuid not null references public.branches (id),
  amount numeric(14, 2) not null check (amount > 0),
  paid_on date not null,
  payment_method text not null check (payment_method in ('bank_transfer', 'cash', 'pos', 'cheque')),
  reference text,
  -- The account the money went into, if Accounts knows it. Always one of the branch's accounts.
  bank_account_id uuid references public.bank_accounts (id),
  -- Who the money came from (the member's name, or the name on the transfer), for the branch to find the member.
  paid_by text not null check (length(trim(paid_by)) > 1),
  note text,
  status text not null default 'with_branch' check (status in ('with_branch', 'logged', 'returned', 'cancelled')),
  requested_by uuid not null references public.staff (id),
  requested_at timestamptz not null default now(),
  -- Filled in when the branch logs it.
  member_id uuid references public.members (id),
  member_plan_id uuid references public.member_plans (id),
  contribution_id uuid unique references public.contributions (id),
  logged_by uuid references public.staff (id),
  logged_at timestamptz,
  -- Filled in when the branch sends it back, or Accounts cancels it.
  decided_by uuid references public.staff (id),
  decided_at timestamptz,
  decision_note text,
  created_at timestamptz not null default now(),
  constraint top_up_requests_logged check ((status = 'logged') = (contribution_id is not null))
);
create index top_up_requests_branch_status_idx on public.top_up_requests (branch_id, status);

-- Rows change only through the functions below.
create or replace function app.top_up_requests_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'top ups are never deleted; cancel them instead' using errcode = 'insufficient_privilege';
  end if;
  if not app.in_workflow() then
    raise exception 'top ups change only through the top up workflow' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger top_up_requests_guard
  before insert or update or delete on public.top_up_requests
  for each row execute function app.top_up_requests_guard();

select app.enable_audit('public.top_up_requests');

alter table public.top_up_requests enable row level security;
create policy "accounts and the branch read top ups" on public.top_up_requests for select to authenticated
  using (
    app.has_branch_permission('accounts.read', branch_id)
    or app.has_branch_permission('members.read', branch_id)
  );

-- A top-up contribution can only be created by logging a top up Accounts sent. Everything else is unchanged.
create or replace function app.contributions_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_plan public.member_plans;
  v_original public.contributions;
begin
  if tg_op = 'DELETE' then
    raise exception 'contributions are never deleted; record a reversal instead' using errcode = 'insufficient_privilege';
  end if;

  if tg_op = 'UPDATE' then
    if not app.in_workflow() then
      raise exception 'contributions are never edited; record a reversal instead' using errcode = 'insufficient_privilege';
    end if;
    return new;
  end if;

  if new.kind = 'top_up' and not app.in_workflow() then
    raise exception 'top ups come from Accounts: log the top up Accounts sent to your branch' using errcode = 'insufficient_privilege';
  end if;

  if new.paid_on > current_date then
    raise exception 'payment date can''t be in the future' using errcode = 'check_violation';
  end if;

  select * into v_plan from public.member_plans where id = new.member_plan_id;
  if v_plan.status <> 'active' then
    raise exception 'contributions can only be recorded on active plans' using errcode = 'check_violation';
  end if;

  new.member_id := v_plan.member_id;
  new.branch_id := v_plan.branch_id;
  new.recorded_by := auth.uid();
  new.recorded_at := now();
  new.verified_by := null;
  new.verified_at := null;

  if new.kind = 'reversal' then
    select * into v_original from public.contributions where id = new.reverses_id;
    if v_original.member_plan_id is distinct from new.member_plan_id then
      raise exception 'a reversal must be on the same plan as the entry it reverses' using errcode = 'check_violation';
    end if;
    if v_original.kind = 'reversal' then
      raise exception 'a reversal can''t itself be reversed' using errcode = 'check_violation';
    end if;
    if new.amount <> -v_original.amount then
      raise exception 'a reversal must be for exactly the original amount' using errcode = 'check_violation';
    end if;
  end if;

  return new;
end;
$$;

-- Accounts records a top up for a branch, or sends one the branch returned to a branch again (the same or another).
create or replace function public.initiate_top_up(
  p_id uuid, p_branch_id uuid, p_amount numeric, p_paid_on date, p_payment_method text, p_reference text,
  p_bank_account_id uuid, p_paid_by text, p_note text
)
returns public.top_up_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.top_up_requests;
  v_bank public.bank_accounts;
begin
  if p_id is not null then
    select * into v_row from public.top_up_requests where id = p_id for update;
    if not found or not app.has_branch_permission('accounts.receipts.record', v_row.branch_id) then
      raise exception 'top up not found' using errcode = 'no_data_found';
    end if;
    if v_row.status <> 'returned' then
      raise exception 'only a top up the branch sent back can be sent again' using errcode = 'check_violation';
    end if;
  end if;

  if p_branch_id is null or not app.has_branch_permission('accounts.receipts.record', p_branch_id) then
    raise exception 'choose a branch you record receipts for' using errcode = 'insufficient_privilege';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'enter the amount received' using errcode = 'check_violation';
  end if;
  if p_paid_on is null or p_paid_on > current_date then
    raise exception 'the date paid can''t be in the future' using errcode = 'check_violation';
  end if;
  if p_payment_method is null or p_payment_method not in ('bank_transfer', 'cash', 'pos', 'cheque') then
    raise exception 'choose how it was paid' using errcode = 'check_violation';
  end if;
  if p_paid_by is null or length(trim(p_paid_by)) < 2 then
    raise exception 'say who paid it, so the branch can find the member' using errcode = 'check_violation';
  end if;
  if p_bank_account_id is not null then
    select * into v_bank from public.bank_accounts where id = p_bank_account_id;
    if not found or v_bank.branch_id <> p_branch_id or not v_bank.is_active then
      raise exception 'the account it was paid into must be one of that branch''s active accounts' using errcode = 'check_violation';
    end if;
  end if;

  perform app.begin_workflow();
  if p_id is null then
    insert into public.top_up_requests (
      top_up_no, branch_id, amount, paid_on, payment_method, reference, bank_account_id, paid_by, note, status,
      requested_by, requested_at
    ) values (
      'TOP-' || lpad(nextval('public.top_up_no_seq')::text, 6, '0'), p_branch_id, p_amount, p_paid_on, p_payment_method,
      nullif(trim(coalesce(p_reference, '')), ''), p_bank_account_id, trim(p_paid_by), nullif(trim(coalesce(p_note, '')), ''),
      'with_branch', auth.uid(), now()
    ) returning * into v_row;
  else
    update public.top_up_requests
       set branch_id = p_branch_id, amount = p_amount, paid_on = p_paid_on, payment_method = p_payment_method,
           reference = nullif(trim(coalesce(p_reference, '')), ''), bank_account_id = p_bank_account_id,
           paid_by = trim(p_paid_by), note = nullif(trim(coalesce(p_note, '')), ''), status = 'with_branch',
           requested_by = auth.uid(), requested_at = now()
     where id = p_id
     returning * into v_row;
  end if;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- The branch logs the top up against the member's plan. Amount, date, method and reference are Accounts'.
create or replace function public.log_top_up(p_id uuid, p_plan_id uuid, p_note text)
returns public.top_up_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.top_up_requests;
  v_plan public.member_plans;
  v_contribution_id uuid;
begin
  select * into v_row from public.top_up_requests where id = p_id for update;
  if not found or not app.has_branch_permission('contributions.record', v_row.branch_id) then
    raise exception 'top up not found' using errcode = 'no_data_found';
  end if;
  if v_row.status <> 'with_branch' then
    raise exception 'this top up isn''t waiting for the branch any more' using errcode = 'check_violation';
  end if;
  if v_row.requested_by = auth.uid() then
    raise exception 'you sent this top up, so someone in the branch must log it' using errcode = 'insufficient_privilege';
  end if;

  select * into v_plan from public.member_plans where id = p_plan_id;
  if not found or v_plan.branch_id <> v_row.branch_id then
    raise exception 'choose a savings plan in this branch' using errcode = 'check_violation';
  end if;
  if v_plan.status <> 'active' then
    raise exception 'top ups can only go on an active plan' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  insert into public.contributions (member_plan_id, member_id, branch_id, kind, amount, paid_on, payment_method, reference, notes)
  values (
    v_plan.id, v_plan.member_id, v_plan.branch_id, 'top_up', v_row.amount, v_row.paid_on, v_row.payment_method, v_row.reference,
    concat_ws(' · ', 'Top up ' || v_row.top_up_no || ' from Accounts', nullif(trim(coalesce(p_note, '')), ''))
  ) returning id into v_contribution_id;

  update public.top_up_requests
     set status = 'logged', member_id = v_plan.member_id, member_plan_id = v_plan.id, contribution_id = v_contribution_id,
         logged_by = auth.uid(), logged_at = now()
   where id = p_id
   returning * into v_row;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- The branch can't match the top up to one of its members: it goes back to Accounts with the reason.
create or replace function public.return_top_up(p_id uuid, p_reason text)
returns public.top_up_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.top_up_requests;
begin
  select * into v_row from public.top_up_requests where id = p_id for update;
  if not found or not app.has_branch_permission('contributions.record', v_row.branch_id) then
    raise exception 'top up not found' using errcode = 'no_data_found';
  end if;
  if v_row.status <> 'with_branch' then
    raise exception 'this top up isn''t waiting for the branch any more' using errcode = 'check_violation';
  end if;
  if p_reason is null or length(trim(p_reason)) < 3 then
    raise exception 'say why it''s going back to Accounts' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.top_up_requests
     set status = 'returned', decided_by = auth.uid(), decided_at = now(), decision_note = trim(p_reason)
   where id = p_id
   returning * into v_row;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- Accounts withdraws a top up the branch hasn't logged (sent in error, or the money was refunded).
create or replace function public.cancel_top_up(p_id uuid, p_reason text)
returns public.top_up_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.top_up_requests;
begin
  select * into v_row from public.top_up_requests where id = p_id for update;
  if not found or not app.has_branch_permission('accounts.receipts.record', v_row.branch_id) then
    raise exception 'top up not found' using errcode = 'no_data_found';
  end if;
  if v_row.status not in ('with_branch', 'returned') then
    raise exception 'only a top up the branch hasn''t logged can be cancelled' using errcode = 'check_violation';
  end if;
  if p_reason is null or length(trim(p_reason)) < 3 then
    raise exception 'say why it''s being cancelled' using errcode = 'check_violation';
  end if;

  perform app.begin_workflow();
  update public.top_up_requests
     set status = 'cancelled', decided_by = auth.uid(), decided_at = now(), decision_note = trim(p_reason)
   where id = p_id
   returning * into v_row;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- Top ups with the names both sides need. Operations can't read Accounts' bank accounts, and neither side reads the
-- other's staff, so this returns only rows in branches the caller may see.
create or replace function public.top_up_list(p_statuses text[] default null)
returns table (
  id uuid, top_up_no text, branch_id uuid, branch_name text, amount numeric, paid_on date, payment_method text,
  reference text, bank_account_id uuid, bank_account_name text, paid_by text, note text, status text,
  requested_by uuid, requested_by_name text, requested_at timestamptz,
  member_id uuid, member_name text, membership_no text, member_plan_id uuid, plan_name text, contribution_id uuid,
  contribution_verified boolean, contribution_status text, logged_by_name text, logged_at timestamptz,
  decided_by_name text, decided_at timestamptz, decision_note text
)
language sql
stable
security definer
set search_path = ''
as $$
  select r.id, r.top_up_no, r.branch_id, br.name, r.amount, r.paid_on, r.payment_method,
         r.reference, r.bank_account_id, b.name, r.paid_by, r.note, r.status,
         r.requested_by, rs.full_name, r.requested_at,
         r.member_id, concat_ws(' ', m.first_name, m.middle_name, m.last_name), m.membership_no, r.member_plan_id, pt.name,
         r.contribution_id, c.verified_at is not null,
         (select t.status::text from public.finance_transactions t
           where t.contribution_id = r.contribution_id and t.status <> 'rejected' limit 1),
         ls.full_name, r.logged_at,
         ds.full_name, r.decided_at, r.decision_note
  from public.top_up_requests r
  join public.branches br on br.id = r.branch_id
  join public.staff rs on rs.id = r.requested_by
  left join public.bank_accounts b on b.id = r.bank_account_id
  left join public.members m on m.id = r.member_id
  left join public.member_plans p on p.id = r.member_plan_id
  left join public.plan_types pt on pt.code = p.plan_type
  left join public.contributions c on c.id = r.contribution_id
  left join public.staff ls on ls.id = r.logged_by
  left join public.staff ds on ds.id = r.decided_by
  where (p_statuses is null or r.status = any (p_statuses))
    and (
      app.has_branch_permission('accounts.read', r.branch_id)
      or app.has_branch_permission('members.read', r.branch_id)
    )
  order by r.requested_at desc
  limit 500;
$$;

revoke all on function public.initiate_top_up(uuid, uuid, numeric, date, text, text, uuid, text, text) from public, anon;
revoke all on function public.log_top_up(uuid, uuid, text) from public, anon;
revoke all on function public.return_top_up(uuid, text) from public, anon;
revoke all on function public.cancel_top_up(uuid, text) from public, anon;
revoke all on function public.top_up_list(text[]) from public, anon;
grant execute on function public.initiate_top_up(uuid, uuid, numeric, date, text, text, uuid, text, text) to authenticated;
grant execute on function public.log_top_up(uuid, uuid, text) to authenticated;
grant execute on function public.return_top_up(uuid, text) to authenticated;
grant execute on function public.cancel_top_up(uuid, text) to authenticated;
grant execute on function public.top_up_list(text[]) to authenticated;

update public.permissions set description = 'Record contributions and reversals, and log top ups Accounts sends'
 where code = 'contributions.record';

-- ====================================================================================================
-- 20261111000010_target_child_savings.sql
-- ====================================================================================================

-- Target savings and Child savings plans.
--
-- Target savings: the member picks a tenure of 3, 6 or 12 months. Nothing is paid out along the way: the principal and
-- every dividend that built up are paid together at the end of the tenure, so these plans stay off the monthly interest
-- payment schedule.
-- Child savings: a 3 month plan with a minimum amount of 200,000 naira.
--
-- The rates below are placeholders until Kuun confirms them, like the Silver, Gold and Platinum rates.

alter table public.plan_types
  -- The tenures, in months, a plan of this type can run for. Null means any maturity date the officer sets.
  add column tenure_months integer[] check (tenure_months is null or (cardinality(tenure_months) > 0 and 0 < all (tenure_months))),
  -- The smallest amount a plan of this type can be opened for. Null means no minimum.
  add column min_amount numeric(14, 2) check (min_amount is null or min_amount > 0),
  -- True when dividends build up and are paid with the principal at maturity, not monthly.
  add column dividends_at_maturity boolean not null default false;

insert into public.plan_types (code, name, description, sort_order, interest_rate, tenure_months, min_amount, dividends_at_maturity)
values
  ('target', 'Target savings', 'Principal and all dividends paid at the end of a 3, 6 or 12 month tenure.', 4, 12, '{3,6,12}', null, true),
  ('child', 'Child savings', 'A 3 month plan with a minimum of 200,000 naira.', 5, 10, '{3}', 200000, false)
on conflict (code) do nothing;

-- New plans must keep to their type's tenures and minimum amount.
create or replace function app.member_plans_type_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_type public.plan_types;
begin
  select * into v_type from public.plan_types where code = new.plan_type;
  if v_type.tenure_months is not null and not exists (
    select 1 from unnest(v_type.tenure_months) as t(months)
    where (new.start_date + make_interval(months => t.months))::date = new.maturity_date
  ) then
    raise exception '% runs for % months: the maturity date must be that long after the start date',
      v_type.name, array_to_string(v_type.tenure_months, ', ', '') using errcode = 'check_violation';
  end if;
  if v_type.min_amount is not null and new.contribution_amount < v_type.min_amount then
    raise exception '% needs at least % naira', v_type.name, to_char(v_type.min_amount, 'FM999,999,999,990.00')
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

create trigger member_plans_type_rules
  before insert on public.member_plans
  for each row execute function app.member_plans_type_rules();

-- Each plan keeps whether it pays at maturity, so a later change to the plan type doesn't change how existing plans pay.
alter table public.member_plans add column dividends_at_maturity boolean not null default false;

create or replace function app.member_plans_rate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    select interest_rate, dividends_at_maturity into new.interest_rate, new.dividends_at_maturity
    from public.plan_types where code = new.plan_type;
  end if;
  return new;
end;
$$;

-- Dividends a plan has built up by a date, counted to its maturity at the latest. Placeholder formula, the same as the
-- monthly one until Kuun confirms it: each verified contribution earns the plan's annual rate divided by 12 for every
-- full month it has been held.
create or replace function public.plan_accrued_dividends(p_plan_id uuid, p_date date default current_date)
returns numeric
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce(sum(round(
           c.amount * p.interest_rate / 100 / 12
           * (extract(year from age(least(p_date, p.maturity_date), c.paid_on)) * 12
              + extract(month from age(least(p_date, p.maturity_date), c.paid_on))),
           2)), 0)::numeric(16, 2)
  from public.member_plans p
  join public.contributions c on c.member_plan_id = p.id
  where p.id = p_plan_id and c.verified_at is not null and c.paid_on <= least(p_date, p.maturity_date);
$$;
revoke all on function public.plan_accrued_dividends(uuid, date) from public, anon;
grant execute on function public.plan_accrued_dividends(uuid, date) to authenticated;

-- The monthly interest payment schedule, now leaving out plans that pay their dividends at maturity.
create or replace function public.interest_payment_schedule(p_date date, p_branch_id uuid default null, p_region_id uuid default null)
returns table (
  member_id uuid, membership_no text, beneficiary_name text, branch_id uuid, branch_name text,
  bank_name text, bank_code text, bank_account_no text, total_savings numeric, interest_rate numeric, amount numeric
)
language sql
stable
security invoker
set search_path = ''
as $$
  with due as (
    select m.*, b.name as branch_name
    from public.members m
    join public.branches b on b.id = m.branch_id
    where m.status = 'approved'
      and m.interest_pay_day is not null
      and (m.interest_pay_day = extract(day from p_date)
           or (p_date = (date_trunc('month', p_date) + interval '1 month - 1 day')::date
               and m.interest_pay_day > extract(day from p_date)))
      and (p_branch_id is null or m.branch_id = p_branch_id)
      and (p_region_id is null or b.region_id = p_region_id)
  ),
  plans as (
    select p.member_id, p.interest_rate, coalesce(sum(c.amount), 0) as savings
    from public.member_plans p
    join due d on d.id = p.member_id
    left join public.contributions c on c.member_plan_id = p.id and c.verified_at is not null and c.paid_on <= p_date
    where p.status = 'active' and p.start_date <= p_date and not p.dividends_at_maturity
    group by p.id
  )
  select d.id, d.membership_no, concat_ws(' ', d.first_name, d.middle_name, d.last_name), d.branch_id, d.branch_name,
         d.bank_name, d.bank_code, d.bank_account_no,
         sum(p.savings)::numeric(16, 2),
         round(sum(p.savings * p.interest_rate) / sum(p.savings), 2),
         sum(round(p.savings * p.interest_rate / 100 / 12, 2))::numeric(16, 2)
  from due d
  join plans p on p.member_id = d.id
  group by d.id, d.membership_no, d.first_name, d.middle_name, d.last_name, d.branch_id, d.branch_name,
           d.bank_name, d.bank_code, d.bank_account_no
  having sum(p.savings) > 0
  order by d.branch_name, d.last_name, d.first_name;
$$;

-- ====================================================================================================
-- 20261111000020_operations_reports_own_branch.sql
-- ====================================================================================================

-- Operations reports: only the Head of Operations sees every branch. Everyone else who opens the Operations reports
-- (Operations Officers, Branch Managers, marketers, credit staff, auditors) sees their own branch only: the branch
-- their role is assigned to, or their home branch if the role was given organisation-wide.
-- Safe to run twice.

insert into public.permissions (code, description) values
  ('reports.all_branches', 'Run Operations reports for every branch')
on conflict (code) do nothing;

insert into public.role_permissions (role_code, permission_code) values
  ('head_of_administration', 'reports.all_branches')
on conflict do nothing;

-- ====================================================================================================
-- 20261113000001_credit_landmark_restructure_penalties.sql
-- ====================================================================================================

-- Credit changes asked for on 2026-11-12/13:
--
--   1. A landmark beside the customer's address on a loan application ("opposite First Bank", "behind the market").
--   2. Restructuring is the Head of Credit's call (credit.approve), and the Head of Business (credit.business_approve)
--      must approve it before the new schedule takes effect. Account officers no longer request restructures.
--   3. Late repayment penalty. When an instalment falls due and isn't paid, what the customer owes grows by a percentage
--      of the unpaid instalment for every day it stays unpaid. The daily rate is set per loan product (Credit > Loan
--      products). Kuun hasn't given the rate yet, so every product starts at a PLACEHOLDER of 0.1% a day.
--
-- How the penalty works
--   * Each day an instalment is overdue, it is charged rate% of what is still unpaid on it (principal + interest; the
--     penalty itself is not charged penalty). Day one is the day after the due date. A repayment dated D stops the
--     charge from the day after D, so paying one day late costs one day.
--   * The penalty is worked out from the schedule and the posted repayments, not stored day by day, so it is always
--     up to date without a nightly job, and reversing a repayment in Accounts puts back exactly the penalty it stopped.
--   * A repayment pays, in order: the overdue instalments (interest then principal, oldest first), then the penalty,
--     then the instalments not yet due. Accounts posts the penalty part to 4150 Loan penalty income.
--   * A loan closes only when the schedule and the penalty are both paid.
--   * A restructure carries any unpaid penalty into the new schedule's first instalment, with the unpaid interest.

-- ---------------------------------------------------------------------------
-- 1. Landmark
-- ---------------------------------------------------------------------------

alter table public.loans
  add column address_landmark text check (address_landmark is null or length(address_landmark) <= 200);

-- ---------------------------------------------------------------------------
-- 2. Restructures: Head of Credit requests, Head of Business approves
-- ---------------------------------------------------------------------------

update public.permissions set description = 'Prepare loan applications, upload documents and record reminders'
 where code = 'credit.manage';
update public.permissions
   set description = 'Approve, return, reject or cancel loans, restructure loans and reassign account officers'
 where code = 'credit.approve';
update public.permissions set description = 'Give the final approval on loans and loan restructures'
 where code = 'credit.business_approve';
update public.roles set description = 'Approves or rejects loans, restructures loans and owns the loan products'
 where code = 'credit_manager';
update public.roles
   set description = 'Gives the final approval on loans and loan restructures after the Head of Credit, before they take effect'
 where code = 'head_of_business';

alter table public.loan_restructures
  add column carried_penalty numeric(14, 2);

create or replace function public.request_loan_restructure(
  p_loan_id uuid, p_tenor_months integer, p_frequency text, p_interest_rate numeric, p_rate_basis text,
  p_interest_method text, p_first_due date, p_reason text
)
returns public.loan_restructures
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_loan public.loans;
  v_row public.loan_restructures;
begin
  select * into v_loan from public.loans where id = p_loan_id for update;
  if not found or not app.has_branch_permission('credit.read', v_loan.branch_id) then
    raise exception 'loan not found' using errcode = 'no_data_found';
  end if;
  if not app.has_branch_permission('credit.approve', v_loan.branch_id) then
    raise exception 'only the Head of Credit can restructure a loan' using errcode = 'insufficient_privilege';
  end if;
  if v_loan.status <> 'active' then
    raise exception 'only active loans can be restructured' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.loan_restructures r where r.loan_id = p_loan_id and r.status = 'pending') then
    raise exception 'a restructure for this loan is already waiting for approval' using errcode = 'check_violation';
  end if;
  if p_first_due is null or p_first_due <= current_date then
    raise exception 'the first new repayment date must be in the future' using errcode = 'check_violation';
  end if;
  if p_frequency = 'quarterly' and p_tenor_months % 3 <> 0 then
    raise exception 'a quarterly loan''s tenor must be a whole number of quarters' using errcode = 'check_violation';
  end if;
  if p_reason is null or length(trim(p_reason)) < 5 then
    raise exception 'say why the loan is being restructured' using errcode = 'check_violation';
  end if;

  insert into public.loan_restructures
    (loan_id, branch_id, tenor_months, repayment_frequency, interest_rate, rate_basis, interest_method, first_repayment_date,
     reason, requested_by)
  values
    (p_loan_id, v_loan.branch_id, p_tenor_months, p_frequency, p_interest_rate, p_rate_basis, p_interest_method, p_first_due,
     trim(p_reason), auth.uid())
  returning * into v_row;
  return v_row;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Late repayment penalty
-- ---------------------------------------------------------------------------

-- PLACEHOLDER rate: 0.1% a day until Kuun gives the real one. Change it per product on Credit > Loan products.
alter table public.loan_products
  add column late_penalty_rate numeric(7, 4) not null default 0.1 check (late_penalty_rate >= 0 and late_penalty_rate <= 10);
comment on column public.loan_products.late_penalty_rate is
  'Percent of an overdue instalment''s unpaid amount added to what the customer owes for each day it stays unpaid. 0.1 is a placeholder.';

alter table public.loan_repayments
  add column penalty numeric(14, 2) not null default 0 check (penalty >= 0);
alter table public.loan_repayments drop constraint loan_repayments_split;
alter table public.loan_repayments add constraint loan_repayments_split check (principal + interest + penalty = amount);

alter table public.finance_transactions
  add column penalty_amount numeric(14, 2) not null default 0 check (penalty_amount >= 0);
alter table public.finance_transactions
  add constraint finance_transactions_penalty check (interest_amount + penalty_amount <= amount);

insert into public.ledger_accounts (code, name, account_type, parent_code, is_group, cash_flow_class, description)
values ('4150', 'Loan penalty income', 'income', '4000', false, 'operating', 'Late repayment penalties charged on overdue loan instalments')
on conflict (code) do nothing;

alter table public.posting_rules
  add column penalty_account text references public.ledger_accounts (code);
update public.posting_rules set penalty_account = '4150', name = 'Loan repayment (principal, interest and penalty)'
 where transaction_type = 'loan_repayment';

-- The penalty a loan's current schedule has run up to the end of p_as_of. Runs with the caller's rights, so a reader
-- only gets figures for loans they can see; the Accounts triggers call it with the owner's rights.
create or replace function app.loan_penalty_accrued(p_loan_id uuid, p_as_of date)
returns numeric
language plpgsql
stable
set search_path = ''
as $$
declare
  v_loan public.loans;
  v_rate numeric;
  v_total numeric := 0;
  v_prev date := null;
  v_paid_p numeric := 0;
  v_paid_i numeric := 0;
  v_pay record;
begin
  select * into v_loan from public.loans where id = p_loan_id;
  if not found or v_loan.schedule_version = 0 or p_as_of is null then
    return 0;
  end if;
  select late_penalty_rate into v_rate from public.loan_products where code = v_loan.product_code;
  if coalesce(v_rate, 0) = 0 then
    return 0;
  end if;

  -- Between two repayment dates what is paid is fixed, so each instalment's unpaid amount is too: charge it for its
  -- overdue days in that stretch. A stretch (v_prev, d] uses the repayments dated on or before v_prev.
  for v_pay in
    select r.paid_on, sum(r.principal) as principal, sum(r.interest) as interest
    from public.loan_repayments r
    where r.loan_id = p_loan_id and r.schedule_version = v_loan.schedule_version and r.reversed_at is null
      and r.paid_on < p_as_of
    group by r.paid_on
    order by r.paid_on
  loop
    v_total := v_total + app.loan_penalty_stretch(p_loan_id, v_loan.schedule_version, v_paid_p, v_paid_i, v_prev, v_pay.paid_on);
    v_paid_p := v_paid_p + v_pay.principal;
    v_paid_i := v_paid_i + v_pay.interest;
    v_prev := v_pay.paid_on;
  end loop;
  v_total := v_total + app.loan_penalty_stretch(p_loan_id, v_loan.schedule_version, v_paid_p, v_paid_i, v_prev, p_as_of);
  return round(v_total * v_rate / 100, 2);
end;
$$;

-- Sum over instalments of (unpaid amount × overdue days in (p_from, p_to]), given what had been paid in that stretch.
-- Payments fill instalments in order, interest and principal separately, the same way loan_schedule_status does.
create or replace function app.loan_penalty_stretch(
  p_loan_id uuid, p_version integer, p_paid_principal numeric, p_paid_interest numeric, p_from date, p_to date
)
returns numeric
language sql
stable
set search_path = ''
as $$
  with inst as (
    select i.due_date, i.principal_due, i.interest_due,
           sum(i.principal_due) over w - i.principal_due as principal_before,
           sum(i.interest_due) over w - i.interest_due as interest_before
    from public.loan_installments i
    where i.loan_id = p_loan_id and i.schedule_version = p_version and i.due_date < p_to
    window w as (order by i.installment_no rows between unbounded preceding and current row)
  )
  select coalesce(sum(
    (principal_due - greatest(0, least(principal_due, p_paid_principal - principal_before))
     + interest_due - greatest(0, least(interest_due, p_paid_interest - interest_before)))
    * greatest(0, p_to - greatest(coalesce(p_from, due_date), due_date))
  ), 0)
  from inst;
$$;

grant execute on function app.loan_penalty_accrued(uuid, date) to authenticated;
grant execute on function app.loan_penalty_stretch(uuid, integer, numeric, numeric, date, date) to authenticated;

-- Splits a payment made on p_as_of: overdue instalments first (interest before principal, oldest first), then the
-- penalty owed, then the instalments not yet due. p_paid_* are what the current schedule has already received.
-- Raises if the payment is more than what is owed.
drop function app.loan_allocate(uuid, numeric, numeric, numeric);
create or replace function app.loan_allocate(
  p_loan_id uuid, p_amount numeric, p_paid_principal numeric, p_paid_interest numeric, p_paid_penalty numeric, p_as_of date
)
returns table (principal numeric, interest numeric, penalty numeric)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_inst record;
  v_paid_p numeric := coalesce(p_paid_principal, 0);
  v_paid_i numeric := coalesce(p_paid_interest, 0);
  v_left numeric := p_amount;
  v_owed numeric := 0;
  v_penalty_owed numeric;
  v_penalty_done boolean := false;
  v_take numeric;
  v_rem numeric;
begin
  principal := 0;
  interest := 0;
  penalty := 0;
  v_penalty_owed := greatest(0, app.loan_penalty_accrued(p_loan_id, p_as_of) - coalesce(p_paid_penalty, 0));
  for v_inst in
    select i.principal_due, i.interest_due, i.due_date
    from public.loan_installments i
    join public.loans l on l.id = i.loan_id and l.schedule_version = i.schedule_version
    where i.loan_id = p_loan_id
    order by i.installment_no
  loop
    if not v_penalty_done and v_inst.due_date >= p_as_of then
      v_owed := v_owed + v_penalty_owed;
      penalty := least(v_left, v_penalty_owed);
      v_left := v_left - penalty;
      v_penalty_done := true;
    end if;

    v_take := least(v_inst.interest_due, v_paid_i);
    v_paid_i := v_paid_i - v_take;
    v_rem := v_inst.interest_due - v_take;
    v_owed := v_owed + v_rem;
    v_take := least(v_left, v_rem);
    v_left := v_left - v_take;
    interest := interest + v_take;

    v_take := least(v_inst.principal_due, v_paid_p);
    v_paid_p := v_paid_p - v_take;
    v_rem := v_inst.principal_due - v_take;
    v_owed := v_owed + v_rem;
    v_take := least(v_left, v_rem);
    v_left := v_left - v_take;
    principal := principal + v_take;
  end loop;
  if not v_penalty_done then
    v_owed := v_owed + v_penalty_owed;
    penalty := least(v_left, v_penalty_owed);
    v_left := v_left - penalty;
  end if;
  if v_left > 0 then
    raise exception 'that is more than the ₦% still owed on this loan', to_char(v_owed, 'FM999,999,999,990.00')
      using errcode = 'check_violation';
  end if;
  return next;
end;
$$;
revoke all on function app.loan_allocate(uuid, numeric, numeric, numeric, numeric, date) from public, anon, authenticated;

-- Unchanged, except that the database also works out the penalty part of a repayment.
create or replace function app.finance_transactions_loans()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_loan public.loans;
  v_paid_p numeric;
  v_paid_i numeric;
  v_paid_pen numeric;
  v_split record;
begin
  if tg_op = 'UPDATE' and app.in_workflow() then
    return new;
  end if;

  if new.transaction_type in ('loan_disbursement', 'loan_repayment') and new.loan_id is null then
    raise exception 'choose the loan this % is for', case when new.direction = 'receipt' then 'repayment' else 'disbursement' end
      using errcode = 'check_violation';
  end if;
  if new.loan_id is null then
    new.loan_schedule_version := null;
    new.penalty_amount := 0;
    return new;
  end if;
  if new.transaction_type not in ('loan_disbursement', 'loan_repayment') then
    raise exception 'only loan disbursements and repayments are linked to a loan' using errcode = 'check_violation';
  end if;
  if tg_op = 'UPDATE' and new.loan_id is distinct from old.loan_id and old.transaction_type = 'loan_disbursement' then
    raise exception 'a disbursement stays with its loan; reject it and raise a new one' using errcode = 'check_violation';
  end if;

  select * into v_loan from public.loans where id = new.loan_id;
  if v_loan.branch_id <> new.branch_id then
    raise exception 'use a bank or cash account of the loan''s branch' using errcode = 'check_violation';
  end if;
  new.member_id := v_loan.member_id;
  new.loan_schedule_version := v_loan.schedule_version;

  if new.transaction_type = 'loan_disbursement' then
    if v_loan.status <> 'approved' then
      raise exception 'only approved loans can be paid out' using errcode = 'check_violation';
    end if;
    if new.amount <> v_loan.approved_amount then
      raise exception 'the disbursement must be the approved amount of ₦%', to_char(v_loan.approved_amount, 'FM999,999,999,990.00')
        using errcode = 'check_violation';
    end if;
    if exists (
      select 1 from public.finance_transactions t
      where t.loan_id = new.loan_id and t.transaction_type = 'loan_disbursement' and t.id <> new.id
        and t.status not in ('rejected', 'reversed')
    ) then
      raise exception 'this loan already has a disbursement in Accounts' using errcode = 'check_violation';
    end if;
    new.interest_amount := 0;
    new.penalty_amount := 0;
    return new;
  end if;

  -- Repayment: the database works out the interest and penalty, after any earlier repayments still being processed.
  if v_loan.status <> 'active' then
    raise exception 'repayments are recorded against active loans' using errcode = 'check_violation';
  end if;
  select coalesce(sum(r.principal), 0), coalesce(sum(r.interest), 0), coalesce(sum(r.penalty), 0)
    into v_paid_p, v_paid_i, v_paid_pen
  from public.loan_repayments r
  where r.loan_id = v_loan.id and r.schedule_version = v_loan.schedule_version and r.reversed_at is null;
  select v_paid_p + coalesce(sum(t.amount - t.interest_amount - t.penalty_amount), 0), v_paid_i + coalesce(sum(t.interest_amount), 0),
         v_paid_pen + coalesce(sum(t.penalty_amount), 0)
    into v_paid_p, v_paid_i, v_paid_pen
  from public.finance_transactions t
  where t.loan_id = v_loan.id and t.transaction_type = 'loan_repayment' and t.id <> new.id
    and t.status in ('draft', 'submitted', 'returned', 'approved')
    and t.created_at < coalesce(new.created_at, now());
  select * into v_split from app.loan_allocate(v_loan.id, new.amount, v_paid_p, v_paid_i, v_paid_pen, new.txn_date);
  new.interest_amount := v_split.interest;
  new.penalty_amount := v_split.penalty;
  return new;
end;
$$;

-- Unchanged, except that posting records the penalty part and a loan closes only when its penalty is paid too.
create or replace function app.finance_transactions_loan_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_loan public.loans;
  v_was_on boolean := app.in_workflow();
  v_paid_p numeric;
  v_paid_i numeric;
  v_paid_pen numeric;
  v_split record;
  v_maturity date;
  v_left numeric;
  v_repayment public.loan_repayments;
begin
  if new.loan_id is null or (tg_op = 'UPDATE' and new.status is not distinct from old.status) then
    return null;
  end if;
  select * into v_loan from public.loans where id = new.loan_id for update;
  perform app.begin_workflow();

  if new.transaction_type = 'loan_disbursement' then
    update public.loans set disbursement_txn_id = new.id, disbursement_txn_no = new.txn_no, disbursement_status = new.status::text
     where id = v_loan.id;
    if new.status = 'posted' then
      update public.loans set status = 'active', disbursed_on = new.txn_date, schedule_version = 1 where id = v_loan.id
      returning * into v_loan;
      v_maturity := app.write_loan_schedule(v_loan, 1, v_loan.approved_amount, new.txn_date, v_loan.first_repayment_date, 0);
      update public.loans set maturity_date = v_maturity where id = v_loan.id;
    elsif new.status = 'reversed' then
      if exists (select 1 from public.loan_repayments r where r.loan_id = v_loan.id and r.reversed_at is null) then
        raise exception 'this loan has repayments; reverse those first' using errcode = 'check_violation';
      end if;
      delete from public.loan_installments where loan_id = v_loan.id;
      update public.loans set status = 'approved', disbursed_on = null, schedule_version = 0, maturity_date = null where id = v_loan.id;
    end if;
  elsif new.status = 'posted' then
    if new.loan_schedule_version is distinct from v_loan.schedule_version or v_loan.status <> 'active' then
      raise exception 'the loan has changed since this repayment was prepared; return it so it can be saved again' using errcode = 'check_violation';
    end if;
    select coalesce(sum(r.principal), 0), coalesce(sum(r.interest), 0), coalesce(sum(r.penalty), 0)
      into v_paid_p, v_paid_i, v_paid_pen
    from public.loan_repayments r
    where r.loan_id = v_loan.id and r.schedule_version = v_loan.schedule_version and r.reversed_at is null;
    select * into v_split from app.loan_allocate(v_loan.id, new.amount, v_paid_p, v_paid_i, v_paid_pen, new.txn_date);
    if v_split.interest <> new.interest_amount or v_split.penalty <> new.penalty_amount then
      raise exception 'other repayments on this loan were posted first, so this one''s interest and penalty split has changed; return it so it can be saved again'
        using errcode = 'check_violation';
    end if;
    insert into public.loan_repayments
      (loan_id, branch_id, finance_transaction_id, txn_no, paid_on, amount, principal, interest, penalty, schedule_version)
    values (v_loan.id, v_loan.branch_id, new.id, new.txn_no, new.txn_date, new.amount,
            new.amount - new.interest_amount - new.penalty_amount, new.interest_amount, new.penalty_amount, v_loan.schedule_version);
    select coalesce(sum(s.outstanding), 0) into v_left from public.loan_schedule_status s where s.loan_id = v_loan.id;
    select v_left + greatest(0, app.loan_penalty_accrued(v_loan.id, greatest(current_date, new.txn_date)) - coalesce(sum(r.penalty), 0))
      into v_left
    from public.loan_repayments r
    where r.loan_id = v_loan.id and r.schedule_version = v_loan.schedule_version and r.reversed_at is null;
    if v_left = 0 then
      update public.loans set status = 'closed', closed_on = new.txn_date where id = v_loan.id;
    end if;
  elsif new.status = 'reversed' then
    select * into v_repayment from public.loan_repayments where finance_transaction_id = new.id;
    if v_repayment.schedule_version <> v_loan.schedule_version then
      raise exception 'this repayment was made before the loan was restructured, so it can''t be reversed here; ask Credit' using errcode = 'check_violation';
    end if;
    update public.loan_repayments set reversed_at = now(), reversal_reason = new.decision_reason where id = v_repayment.id;
    if v_loan.status = 'closed' then
      update public.loans set status = 'active', closed_on = null where id = v_loan.id;
    end if;
  end if;

  if not v_was_on then
    perform app.end_workflow();
  end if;
  return null;
end;
$$;

-- Unchanged, except that the penalty part of a loan repayment goes to the penalty income account.
create or replace function app.post_finance_transaction(p_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_txn public.finance_transactions;
  v_rule public.posting_rules;
  v_bank public.bank_accounts;
  v_entry_id uuid;
  v_bank_line_id uuid;
  v_match_id uuid;
  v_description text;
begin
  select * into v_txn from public.finance_transactions where id = p_id;
  select * into v_rule from public.posting_rules where transaction_type = v_txn.transaction_type;
  select * into v_bank from public.bank_accounts where id = v_txn.bank_account_id;
  v_description := v_txn.txn_no || ' ' || v_rule.name || coalesce(' - ' || v_txn.counterparty, '');

  perform app.begin_workflow();
  insert into public.journal_entries (branch_id, entry_date, description, source, transaction_id, status, created_by, posted_by, posted_at)
  values (v_txn.branch_id, v_txn.txn_date, v_description, 'transaction', v_txn.id, 'draft', v_txn.created_by, auth.uid(), now())
  returning id into v_entry_id;

  if v_txn.direction = 'receipt' then
    insert into public.journal_lines (entry_id, line_no, account_code, debit, member_id, bank_account_id, description)
    values (v_entry_id, 1, v_bank.ledger_account_code, v_txn.amount, v_txn.member_id, v_bank.id, v_txn.description)
    returning id into v_bank_line_id;
    if v_txn.amount - v_txn.interest_amount - v_txn.penalty_amount > 0 then
      insert into public.journal_lines (entry_id, line_no, account_code, credit, member_id, description)
      values (v_entry_id, 2, v_rule.credit_account, v_txn.amount - v_txn.interest_amount - v_txn.penalty_amount, v_txn.member_id,
              v_txn.description);
    end if;
    if v_txn.interest_amount > 0 then
      insert into public.journal_lines (entry_id, line_no, account_code, credit, member_id, description)
      values (v_entry_id, 3, v_rule.interest_account, v_txn.interest_amount, v_txn.member_id, 'Interest');
    end if;
    if v_txn.penalty_amount > 0 then
      insert into public.journal_lines (entry_id, line_no, account_code, credit, member_id, description)
      values (v_entry_id, 4, coalesce(v_rule.penalty_account, v_rule.interest_account), v_txn.penalty_amount, v_txn.member_id,
              'Late repayment penalty');
    end if;
  else
    insert into public.journal_lines (entry_id, line_no, account_code, debit, member_id, description)
    values (v_entry_id, 1, v_rule.debit_account, v_txn.amount, v_txn.member_id, v_txn.description);
    insert into public.journal_lines (entry_id, line_no, account_code, credit, member_id, bank_account_id, description)
    values (v_entry_id, 2, v_bank.ledger_account_code, v_txn.amount, v_txn.member_id, v_bank.id, v_txn.description)
    returning id into v_bank_line_id;
  end if;

  perform app.assert_balanced(v_entry_id);
  update public.journal_entries set status = 'posted' where id = v_entry_id;

  -- Only real bank accounts are reconciled against statements.
  if v_txn.statement_line_id is not null and v_bank.kind = 'bank' then
    insert into public.bank_matches (bank_account_id, branch_id, method, note)
    values (v_bank.id, v_bank.branch_id, 'posted', 'Posted from the statement line')
    returning id into v_match_id;
    insert into public.bank_match_ledger_lines (match_id, journal_line_id) values (v_match_id, v_bank_line_id);
    update public.bank_statement_lines set status = 'matched', match_id = v_match_id where id = v_txn.statement_line_id;
  end if;

  update public.finance_transactions
     set status = 'posted', posted_at = now(), journal_entry_id = v_entry_id
   where id = p_id;
  perform app.end_workflow();
  return v_entry_id;
end;
$$;
revoke all on function app.post_finance_transaction(uuid) from public, anon, authenticated;

-- The Head of Business's decision on a restructure the Head of Credit asked for. On approval, the principal still owed,
-- plus interest already due and unpaid and any unpaid penalty, gets a new schedule on the new terms.
create or replace function public.decide_loan_restructure(p_id uuid, p_approve boolean, p_note text)
returns public.loan_restructures
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.loan_restructures;
  v_loan public.loans;
  v_principal numeric;
  v_carried numeric;
  v_penalty numeric;
  v_maturity date;
begin
  select * into v_row from public.loan_restructures where id = p_id for update;
  if not found or not app.has_branch_permission('credit.read', v_row.branch_id) then
    raise exception 'restructure not found' using errcode = 'no_data_found';
  end if;
  if not app.has_branch_permission('credit.business_approve', v_row.branch_id) then
    raise exception 'only the Head of Business can approve a restructure' using errcode = 'insufficient_privilege';
  end if;
  if v_row.status <> 'pending' then
    raise exception 'this restructure has already been decided' using errcode = 'check_violation';
  end if;
  if auth.uid() = v_row.requested_by then
    raise exception 'you requested this restructure, so someone else must decide it' using errcode = 'insufficient_privilege';
  end if;
  select * into v_loan from public.loans where id = v_row.loan_id for update;

  if not p_approve then
    if p_note is null or length(trim(p_note)) < 5 then
      raise exception 'give the reason for declining the restructure' using errcode = 'check_violation';
    end if;
    update public.loan_restructures set status = 'rejected', decided_by = auth.uid(), decided_at = now(), decision_note = trim(p_note)
     where id = p_id returning * into v_row;
    return v_row;
  end if;

  if v_loan.status <> 'active' then
    raise exception 'the loan is no longer active' using errcode = 'check_violation';
  end if;
  if exists (
    select 1 from public.finance_transactions t
    where t.loan_id = v_loan.id and t.transaction_type = 'loan_repayment' and t.status in ('draft', 'submitted', 'returned', 'approved')
  ) then
    raise exception 'a repayment for this loan is still being processed in Accounts; post or reject it first' using errcode = 'check_violation';
  end if;

  select coalesce(sum(s.principal_due - s.principal_paid), 0),
         coalesce(sum(s.interest_due - s.interest_paid) filter (where s.due_date <= current_date), 0)
    into v_principal, v_carried
  from public.loan_schedule_status s where s.loan_id = v_loan.id;
  if v_principal <= 0 then
    raise exception 'there is no principal left to restructure' using errcode = 'check_violation';
  end if;
  select greatest(0, app.loan_penalty_accrued(v_loan.id, current_date) - coalesce(sum(r.penalty), 0)) into v_penalty
  from public.loan_repayments r
  where r.loan_id = v_loan.id and r.schedule_version = v_loan.schedule_version and r.reversed_at is null;

  perform app.begin_workflow();
  update public.loans
     set tenor_months = v_row.tenor_months, repayment_frequency = v_row.repayment_frequency, interest_rate = v_row.interest_rate,
         rate_basis = v_row.rate_basis, interest_method = v_row.interest_method, first_repayment_date = v_row.first_repayment_date,
         schedule_version = v_loan.schedule_version + 1
   where id = v_loan.id
   returning * into v_loan;
  v_maturity := app.write_loan_schedule(v_loan, v_loan.schedule_version, v_principal, current_date, v_row.first_repayment_date,
                                        v_carried + v_penalty);
  update public.loans set maturity_date = v_maturity where id = v_loan.id;
  update public.loan_restructures
     set status = 'approved', decided_by = auth.uid(), decided_at = now(), decision_note = nullif(trim(p_note), ''),
         outstanding_principal = v_principal, carried_interest = v_carried, carried_penalty = v_penalty,
         from_version = v_loan.schedule_version - 1, to_version = v_loan.schedule_version
   where id = p_id
   returning * into v_row;
  perform app.end_workflow();
  return v_row;
end;
$$;

-- The loan book, with the penalty added at the end: what the current schedule has run up, what has been paid towards
-- penalties (all schedules), what is still owed, and the product's daily rate.
create or replace view public.loan_book with (security_invoker = true) as
select l.id, l.loan_no, l.branch_id, b.region_id, l.member_id,
       concat_ws(' ', m.first_name, m.middle_name, m.last_name) as member_name, m.membership_no,
       l.product_code, p.name as product_name, l.customer_category, l.account_officer_id, l.status,
       l.amount_requested, l.approved_amount, l.tenor_months, l.repayment_frequency, l.interest_rate, l.rate_basis,
       l.interest_method, l.risk_rating, l.created_at, l.submitted_at, l.appraised_at, l.approved_at, l.decided_at,
       l.disbursement_status, l.disbursed_on, l.maturity_date, l.closed_on,
       coalesce(s.principal_due, 0)::numeric(16, 2) as schedule_principal,
       coalesce(s.interest_due, 0)::numeric(16, 2) as schedule_interest,
       coalesce(r.principal, 0)::numeric(16, 2) as principal_repaid,
       coalesce(r.interest, 0)::numeric(16, 2) as interest_repaid,
       (coalesce(s.principal_due, 0) - coalesce(s.principal_paid, 0))::numeric(16, 2) as outstanding_principal,
       (coalesce(s.interest_due, 0) - coalesce(s.interest_paid, 0))::numeric(16, 2) as outstanding_interest,
       (coalesce(r.principal, 0) + coalesce(r.interest, 0) + coalesce(s.principal_due, 0) + coalesce(s.interest_due, 0)
         - coalesce(s.principal_paid, 0) - coalesce(s.interest_paid, 0))::numeric(16, 2) as total_expected,
       coalesce(s.overdue_amount, 0)::numeric(16, 2) as overdue_amount,
       coalesce(s.overdue_principal, 0)::numeric(16, 2) as overdue_principal,
       coalesce(s.missed, 0)::integer as missed_repayments,
       case when s.oldest_overdue is not null then current_date - s.oldest_overdue else 0 end as days_past_due,
       s.next_due_date, coalesce(s.next_due_amount, 0)::numeric(16, 2) as next_due_amount,
       coalesce(s.remaining, 0)::integer as remaining_installments,
       r.last_paid_on,
       p.late_penalty_rate,
       coalesce(r.penalty, 0)::numeric(16, 2) as penalty_repaid,
       pen.outstanding::numeric(16, 2) as penalty_outstanding
from public.loans l
join public.branches b on b.id = l.branch_id
join public.members m on m.id = l.member_id
join public.loan_products p on p.code = l.product_code
left join lateral (
  select sum(x.principal_due) as principal_due, sum(x.interest_due) as interest_due,
         sum(x.principal_paid) as principal_paid, sum(x.interest_paid) as interest_paid,
         sum(x.outstanding) filter (where x.due_date < current_date) as overdue_amount,
         sum(x.principal_due - x.principal_paid) filter (where x.due_date < current_date) as overdue_principal,
         count(*) filter (where x.due_date < current_date and x.outstanding > 0) as missed,
         min(x.due_date) filter (where x.due_date < current_date and x.outstanding > 0) as oldest_overdue,
         min(x.due_date) filter (where x.due_date >= current_date and x.outstanding > 0) as next_due_date,
         (array_agg(x.outstanding order by x.installment_no) filter (where x.due_date >= current_date and x.outstanding > 0))[1]
           as next_due_amount,
         count(*) filter (where x.outstanding > 0) as remaining
  from public.loan_schedule_status x
  where x.loan_id = l.id
) s on true
left join lateral (
  select sum(rp.principal) as principal, sum(rp.interest) as interest, sum(rp.penalty) as penalty, max(rp.paid_on) as last_paid_on,
         sum(rp.penalty) filter (where rp.schedule_version = l.schedule_version) as penalty_this_schedule
  from public.loan_repayments rp
  where rp.loan_id = l.id and rp.reversed_at is null
) r on true
left join lateral (
  -- Only an active loan can owe a penalty: a closed one paid it before closing.
  select case when l.status = 'active'
              then greatest(0, app.loan_penalty_accrued(l.id, current_date) - coalesce(r.penalty_this_schedule, 0))
              else 0 end as outstanding
) pen on true;
grant select on public.loan_book to authenticated;
